function deltaEncode(values) {
  if (values.length === 0) return [];
  const deltas = [values[0]];
  for (let i = 1; i < values.length; i++) {
    deltas.push(values[i] - values[i - 1]);
  }
  return deltas;
}

const timestamps = [1000000, 1000010, 1000021, 1000031, 1000042];
console.log(deltaEncode(timestamps));
// [1000000, 10, 11, 10, 11]
